SELECT toString(properties.action) AS Action, toString(properties.surface) AS Surface, uniqExact(person_id) AS People, count() AS Actions, round(quantile(0.95)(toFloat(properties.duration_ms))) AS p95_ms FROM events WHERE event='product_action_completed' AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY Action,Surface ORDER BY People DESC LIMIT 100
